import{_ as t,c as n,o as i,ai as a}from"./chunks/framework.CD-XKvSj.js";const c=JSON.parse('{"title":"Butter bei die Fische Meeting","description":"","frontmatter":{"title":"Butter bei die Fische Meeting","date":"2026-09-23","banner":"assets/events/20260923_Butter_bei_die_Fische_Meeting_banner.svg","bannerMobile":"assets/events/20260923_Butter_bei_die_Fische_Meeting_banner_mobile.svg","bannerSmall":"assets/events/20260923_Butter_bei_die_Fische_Meeting_banner_small.svg","backgroundhex":"#128256ff","tags":["neonephos","community"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_09_23_Butter_bei_die_Fische_Meeting.md","filePath":"events/2026_09_23_Butter_bei_die_Fische_Meeting.md"}'),o={name:"events/2026_09_23_Butter_bei_die_Fische_Meeting.md"};function s(r,e,d,_,h,p){return i(),n("div",null,e[0]||(e[0]=[a('<h2 id="butter-bei-die-fische-lets-get-down-to-business" tabindex="-1">Butter bei die Fische - Lets get down to business! <a class="header-anchor" href="#butter-bei-die-fische-lets-get-down-to-business" aria-label="Permalink to &quot;Butter bei die Fische - Lets get down to business!&quot;">​</a></h2><p>Several NNF members met in Hamburg (thus the &quot;Butter bei die Fische&quot;) and organically identified a potential opportunity to work together, and we now want to bring that idea to the wider community. The proposal is to put digital sovereignty into practice by building an end-to-end environment where different organizations each contribute a piece. We want to test whether independently provided open source components can work together across providers and environments.</p><p>The focus is on interoperability, scale, portability, federation, and creating agency.</p><p>This meeting is an open discussion to hear the proposals and ideas, challenge it, and decide together whether and how to take it forward.</p><h3 id="agenda" tabindex="-1">Agenda <a class="header-anchor" href="#agenda" aria-label="Permalink to &quot;Agenda&quot;">​</a></h3><p><strong>15:00 – 15:10</strong> Introduction, Recap, and Opening</p><p><strong>15:10 – 15:30</strong> Member Contribution Suggestions</p><p><strong>15:30 – 15:45</strong> Open Discussion &amp; Q&amp;A</p><p><strong>15:45 – 16:00</strong> Next Steps &amp; Decision on Moving Forward</p><hr><h3 id="event-details" tabindex="-1">Event Details <a class="header-anchor" href="#event-details" aria-label="Permalink to &quot;Event Details&quot;">​</a></h3><p>📅 <strong>Wednesday, September 23, 2026</strong></p><p>🕒 <strong>15:00 (Europe/Madrid)</strong></p><h3 id="join-the-meeting" tabindex="-1">Join the Meeting <a class="header-anchor" href="#join-the-meeting" aria-label="Permalink to &quot;Join the Meeting&quot;">​</a></h3><p>🔗 <a href="https://zoom-lfx.platform.linuxfoundation.org/meeting/92022951624?password=1f5b2cd4-dd31-4416-a8db-039822cabb40" target="_blank" rel="noreferrer">HERE</a></p>',15)]))}const g=t(o,[["render",s]]);export{c as __pageData,g as default};
